BEGIN TRANSACTION;
UPDATE DB1.S2.T1 SET C6 = CURRENT_TIMESTAMP();
COMMIT;

BEGIN WORK;
DELETE FROM DB1.S1.LOG1 WHERE C2 < DATEADD('DAY', -30, CURRENT_TIMESTAMP());
ROLLBACK;

TRUNCATE TABLE DB1.S2.T2;
TRUNCATE IF EXISTS DB1.S2.T1;

ALTER ACCOUNT SET TIMEZONE = 'America/New_York';
ALTER TABLE DB1.S2.T1 ADD COLUMN C7 VARCHAR(50);
ALTER TASK DB1.S2.TASK1 RESUME;
ALTER WAREHOUSE WH1 SUSPEND;
ALTER WAREHOUSE WH1 SET WAREHOUSE_SIZE = 'Small';
